const DESTINATION_BY_MARKER_ID = new Map(
  HARTHMERE_LEGACY_PROTECTION_ESCORT_DESTINATIONS.map((destination) => [
    destination.markerId,
    destination,
  ])
);

export function harthmereLegacyProtectionEscortDestinationForMarkerId(
  markerId: string | undefined
) {
  return markerId ? DESTINATION_BY_MARKER_ID.get(markerId) : undefined;
}
